import { report } from "../report/index.js";
/**
 * Checks whitespace around at-rule names.
 * @param options - The root, the checker, the result, the syntax, the rule's configured name and its fix.
 */
export function atRuleNameSpaceChecker(options) {
    options.root.walkAtRules((atRule) => {
        if (!options.syntax.isStandardAtRule(atRule))
            return;
        checkColon(`@${atRule.name}${atRule.raws.afterName || ``}${atRule.params}`, atRule.name.length, atRule);
    });
    /**
     * Checks one at-rule.
     * @param source - The at-rule's text.
     * @param index - The index to check.
     * @param node - The at-rule.
     */
    function checkColon(source, index, node) {
        options.locationChecker({
            source,
            index,
            err: (m) => {
                // Under Less the whitespace behind `@import` and `@plugin` makes them directives, so the warning stands over a file the fix would change the meaning of
                let fix = options.syntax.readsWhitespaceBehindAtRuleName(node) ? null : options.fix;
                report({
                    message: m,
                    node,
                    index,
                    endIndex: index,
                    result: options.result,
                    ruleName: options.checkedRuleName,
                    ...(fix && { fix: () => fix(node) }),
                });
            },
            errTarget: `@${node.name}`,
        });
    }
}
